import math

def check_expression(n):
    # E(n) = 3 * ((n+2)! + 1) / (2n - 1)
    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return "Undefined (n=0.5)", False # Should not happen for integer n >= 6

    if numerator % denominator == 0:
        return numerator // denominator, True
    else:
        return None, False

values_to_check = [6, 7, 8, 9, 10]
results = {}

for n in values_to_check:
    result, is_integer = check_expression(n)
    results[n] = {"result": result, "is_integer": is_integer}

print("Results:")
for n, data in results.items():
    print(f"n={n}: Integer? {data['is_integer']} (Value: {data['result']})")

import math

def check_prime_constraint(p):
    n = (p + 1) // 2
    # p must divide 3 * ((p+5)/2)! + 1
    # Since p=2n-1, (p+5)/2 = (2n-1+5)/2 = n+2

    # We are checking if p divides 3 * (n+2)! + 1

    try:
        numerator = 3 * math.factorial(n + 2) + 1
        if numerator % p == 0:
            return True, numerator
        else:
            return False, numerator
    except OverflowError:
        return False, "Overflow"

# Test primes p > 11
p_values = [13, 17, 19, 23]

results = {}
for p in p_values:
    is_solution, num = check_prime_constraint(p)
    results[p] = is_solution

print(results)

import math

def E(n):
    # E(n) = 3 * ((n+2)! + 1) / (2n - 1)
    if 2 * n - 1 == 0:
        return None # Should not happen for non-negative integers

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1

        # Check if it's an integer
        if numerator % denominator == 0:
            return numerator // denominator
        else:
            return None
    except OverflowError:
        return "Overflow"

N_values = [0, 1, 2, 4, 6, 7, 8, 9, 10]
results = {}
for n in N_values:
    result = E(n)
    results[n] = result

print(results)
